<template><section class="section"><div class="container card scheduling"><div class="stack"><span class="eyebrow">{{ label('Next step', 'Siguiente paso') }}</span><h2>{{ label('Continue with an approved scheduling route', 'Continúa con una ruta de agenda aprobada') }}</h2><p>{{ label('When scheduling is configured, the destination is supplied through public runtime configuration. Otherwise the contact form remains available.', 'Cuando la agenda está configurada, el destino proviene de la configuración pública. De lo contrario, el formulario de contacto permanece disponible.') }}</p></div><BaseButton v-if="safeUrl" :href="safeUrl">{{ label('Open scheduling', 'Abrir agenda') }}</BaseButton><BaseButton v-else :to="localizePath('/contact')">{{ label('Contact sales', 'Contactar ventas') }}</BaseButton></div></section></template>
<script setup lang="ts">const{locale,localizePath}=useLocale();const config=useRuntimeConfig();const label=(en:string,es:string)=>locale.value==='es'?es:en;const safeUrl=computed(()=>{try{const value=String(config.public.schedulingUrl||'');if(!value)return '';const url=new URL(value);return url.protocol==='https:'?url.toString():''}catch{return ''}})</script>
<style scoped>.scheduling{display:flex;gap:2rem;align-items:center;justify-content:space-between}.scheduling p{max-width:54rem;color:var(--text-secondary)}@media(max-width:45rem){.scheduling{align-items:flex-start;flex-direction:column}}</style>
